"""F1 (version 2) method overview, redesigned. Graphic generated by code written by Claude (AI, chat) on 2026-10-06.
Schematic only: every curve and dot is ILLUSTRATIVE (synthetic shapes), not data. The numbers drawn are fixed design
values recorded in frozen/frozen_spec.json and decisions.md (caliper 0.0747; windows; 88% rule; run-not-before dates).
Usage: python paper_template/figures/f1_method_v2.py -> F1_method_v2.pdf"""
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch, Rectangle
from figstyle import BLUE, ORANGE, INK, INK2, GRID, FULL, save

MAG, EUV, NEU = "#eaf1f8", "#fdeee6", "#f2f2ef"
plt.rcParams.update({"font.family": "sans-serif", "font.size": 7.5})
FH = 5.7
fig = plt.figure(figsize=(FULL, FH))
ax = fig.add_axes([0, 0, 1, 1]); ax.set_xlim(0, 1); ax.set_ylim(0, 1); ax.axis("off")
DY = 0.034 * 5.7 / FH            # title offset

def card(x, y, w, h, bg, num, title, edge=INK2, ls="-", lw=0.9):
    ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0,rounding_size=0.012", fc=bg, ec=edge, lw=lw, ls=ls))
    tx = x + 0.014
    if num:
        ax.add_patch(plt.Circle((x + 0.026, y + h - DY), 0.0125, color=INK, zorder=3, transform=ax.transData))
        ax.text(x + 0.026, y + h - DY, num, color="white", ha="center", va="center", fontsize=7, weight="bold", zorder=4)
        tx = x + 0.047
    ax.text(tx, y + h - DY, title, ha="left", va="center", fontsize=8.2, weight="bold", color=INK)

def note(x, y, w, s):
    ax.text(x + w / 2, y, s, ha="center", va="center", fontsize=6.6, color=INK2, linespacing=1.25)

def inset(x, y, w, h, frame=True):
    a = fig.add_axes([x, y, w, h]); a.set_xticks([]); a.set_yticks([]); a.patch.set_alpha(0)
    for s in a.spines: a.spines[s].set_visible(False)
    if frame:
        for s in ("left", "bottom"): a.spines[s].set_visible(True); a.spines[s].set_color(INK2); a.spines[s].set_linewidth(0.6)
    return a

def arrow(p, q, rad=0.0):
    ax.add_patch(FancyArrowPatch(p, q, arrowstyle="-|>", mutation_scale=9, lw=1.0, color=INK2,
                                 connectionstyle=f"arc3,rad={rad}", zorder=5, shrinkA=0, shrinkB=0))

rng = np.random.RandomState(3)
W, G, X0 = 0.318, 0.0145, 0.008
XS = [X0, X0 + W + G, X0 + 2 * (W + G)]
R1y, R1h = 0.655, 0.335
R2y, R2h = 0.305, 0.315
R3y, R3h = 0.075, 0.17

# ---------------- row 1
x = XS[0]; card(x, R1y, W, R1h, MAG, "1", "Magnetic data (SHARP)")
a = inset(x + 0.04, R1y + 0.115, W - 0.08, 0.15)
a.bar(range(10), [0.9, 0.75, 0.82, 0.55, 0.62, 0.95, 0.7, 0.4, 0.5, 0.3], color=INK2, width=0.65); a.set_ylim(0, 1.05)
a.set_xlabel("10 SHARP features per magnetic patch", fontsize=6.5, labelpad=2)
note(x, R1y + 0.05, W, "HMI, hourly\nQUALITY = 0, |lon| ≤ 45°")

x = XS[1]; card(x, R1y, W, R1h, MAG, "2", "Magnetic gate")
a = inset(x + 0.04, R1y + 0.115, W - 0.08, 0.15)
tt = np.linspace(0, 10, 300); sc = 0.55 * np.sin(tt / 1.6) + 0.12 * np.sin(tt * 2.3) + 0.05
a.fill_between(tt, -0.95, 0.95, where=sc >= 0.3, color=GRID, lw=0)
a.plot(tt, sc, color=INK, lw=1.0); a.axhline(0.3, color=INK2, ls="--", lw=0.8)
a.set_ylim(-0.95, 0.95); a.set_xlim(0, 10); a.set_xlabel("time (hours)", fontsize=6.5, labelpad=2); a.set_ylabel("gate score", fontsize=6.5, labelpad=2)
a.text(9.9, 0.36, "frozen threshold", fontsize=6, ha="right", va="bottom", color=INK2)
a.text(2.55, -0.85, "alarm hours", fontsize=6, ha="center", color=INK)
note(x, R1y + 0.05, W, "Bobra & Couvidat-style SVM,\ncross-validated on 2010–2019")

x = XS[2]; card(x, R1y, W, R1h, NEU, "3", "Alarm episode")
a = inset(x + 0.02, R1y + 0.085, W - 0.04, 0.19, frame=False); a.set_xlim(-52, 52); a.set_ylim(-0.3, 4.4)
a.plot([-48, 48], [0.7, 0.7], color=INK2, lw=0.8)
for v, lab in [(-48, "−48 h"), (-24, "−24 h"), (0, "t"), (24, "+24 h"), (48, "+48 h")]:
    a.plot([v, v], [0.55, 0.85], color=INK2, lw=0.8)
    a.text(v, 0.05, lab, ha="center", va="bottom", fontsize=6, color=INK if lab == "t" else INK2, weight="bold" if lab == "t" else None)
a.plot([0, 0], [0.55, 4.3], color=INK, lw=1.2)
a.add_patch(Rectangle((-48, 3.35), 48, 0.75, fc=GRID, ec="none")); a.text(-24, 3.72, "flare history", ha="center", va="center", fontsize=6.2)
a.add_patch(Rectangle((-24, 2.3), 24, 0.75, fc="#f6c4ad", ec="none")); a.text(-12.5, 2.67, "AIA 94 Å", ha="center", va="center", fontsize=5.6)
a.add_patch(Rectangle((0, 1.25), 24, 0.75, fc="#c9dcf0", ec="none")); a.text(12, 1.62, "M1+?", ha="center", va="center", fontsize=6)
a.add_patch(Rectangle((24, 1.25), 24, 0.75, fc="none", ec=INK2, ls=":", lw=0.8)); a.text(36, 1.62, "delayed", ha="center", va="center", fontsize=5.8, color=INK2)
note(x, R1y + 0.05, W, "t: first eligible alarm hour*\ntrue: M1+ flare starts in (t, t+24 h]\ndelayed alarms count as false")

for i in range(2):
    arrow((XS[i] + W + 0.001, R1y + R1h / 2), (XS[i + 1] - 0.001, R1y + R1h / 2))

# ---------------- row 2
x = XS[0]; card(x, R2y, W, R2h, NEU, "4", "Magnetic twins")
a = inset(x + 0.04, R2y + 0.115, W - 0.08, 0.12); a.spines["left"].set_visible(False)
a.set_xlim(-1.6, 0.6); a.set_ylim(-0.6, 1.5); a.set_xlabel("gate score", fontsize=6.5, labelpad=2)
a.scatter(rng.uniform(-1.5, 0.5, 16), rng.uniform(-0.45, 0.0, 16), s=9, color="#c9c9c5", zorder=1)
a.scatter([-0.46], [0.45], marker="^", s=42, color=ORANGE, zorder=3)
a.scatter([-0.40], [0.45], marker="o", s=32, facecolor="white", edgecolor=INK2, lw=1.1, zorder=3)
a.annotate("", xy=(-0.29, 1.05), xytext=(-0.57, 1.05), arrowprops=dict(arrowstyle="<->", lw=0.7, color=INK))
a.text(-0.43, 1.2, "|Δ score| ≤ 0.0747", ha="center", va="bottom", fontsize=6.2)
ax.scatter([x + 0.219], [R2y + R2h - DY], marker="^", s=18, color=ORANGE, zorder=6)
ax.text(x + 0.229, R2y + R2h - DY, "true", fontsize=6.3, va="center")
ax.scatter([x + 0.268], [R2y + R2h - DY], marker="o", s=15, facecolor="white", edgecolor=INK2, zorder=6)
ax.text(x + 0.278, R2y + R2h - DY, "false", fontsize=6.3, va="center")
note(x, R2y + 0.045, W, "nearest false alarm from another\nHARP; each false alarm used once")

x = XS[1]; card(x, R2y, W, R2h, EUV, "5", "Restlessness, CV$_{\\rm box}$")
a = inset(x + 0.04, R2y + 0.115, W - 0.08, 0.13)
th = np.linspace(-24, 0, 121); y = 3.6 + 0.012 * th + 0.08 * np.sin(th / 1.3) + rng.normal(0, 0.04, th.size)
y[18:24] += np.array([0.3, 0.8, 1.0, 0.7, 0.35, 0.15])
fit = np.polyval(np.polyfit(th, y, 1), th); sd = np.std(y - fit, ddof=1)
a.fill_between(th, fit - sd, fit + sd, color="#f6c4ad", lw=0, label="± 1 SD of residuals")
a.plot(th, y, color=ORANGE, lw=0.8); a.plot(th, fit, color=INK, ls="--", lw=0.8)
a.set_xlim(-24, 0); a.set_xlabel("hours before t (12-min frames)", fontsize=6.5, labelpad=2)
note(x, R2y + 0.045, W, "box-mean AIA 94 Å brightness\nCV$_{\\rm box}$ = SD(residuals) ÷ mean")

x = XS[2]; card(x, R2y, W, R2h, MAG, "6", "Filter models")
rows = [("A", "gate score + C, M, X flare counts"),
        ("C", "A + time since last C1+ flare"),
        ("+CV", "A or C + log$_{10}$ CV$_{\\rm box}$"),
        ("C+", "C$_{\\rm CV}$ keeps OR C1+ in prior 24 h\n(development origin reported)")]
for k, (m, d) in enumerate(rows):
    yy = R2y + R2h - 0.075 - k * 0.045
    ax.add_patch(FancyBboxPatch((x + 0.016, yy - 0.014), 0.042, 0.028, boxstyle="round,pad=0,rounding_size=0.006",
                                fc="white", ec=INK2, lw=0.7))
    ax.text(x + 0.037, yy, m, ha="center", va="center", fontsize=6.6, weight="bold")
    ax.text(x + 0.068, yy, d, ha="left", va="center", fontsize=6.5, color=INK)
note(x, R2y + 0.045, W, "logistic regression; thresholds retain\n≥88% of region-weighted true episodes\n(out-of-fold development predictions)")

# row1 -> row2: episode feeds twins and CV (bus line); CV feeds the models
bus = R2y + R2h + 0.0175
ax.plot([XS[2] + W / 2, XS[2] + W / 2], [R1y - 0.001, bus], color=INK2, lw=1.0)
ax.plot([XS[0] + W / 2, XS[2] + W / 2], [bus, bus], color=INK2, lw=1.0)
arrow((XS[0] + W / 2, bus), (XS[0] + W / 2, R2y + R2h + 0.002))
arrow((XS[1] + W / 2, bus), (XS[1] + W / 2, R2y + R2h + 0.002))
arrow((XS[1] + W + 0.001, R2y + R2h / 2), (XS[2] - 0.001, R2y + R2h / 2))

# ---------------- row 3: tests
tests = [(XS[0], "Twins test (primary)", "median CV$_{\\rm box}$ of true alarms ÷ median\nof their twins; 95% CI with pairs\nresampled by true-alarm HARP", "-"),
         (XS[1], "Registered follow-up", "registered; not yet run\nLook 1: 17 Aug–3 Sep 2026, 23:00 TAI\nearly run (amended 9 Oct 2026)\nLook 2: C+; run ≥15 Mar 2027", "--"),
         (XS[2], "Filter test", "with vs without CV$_{\\rm box}$ at frozen\nthresholds: false alarms removed\n(D$_{\\rm false}$), true kept (D$_{\\rm true}$)", "-")]
for x, title, body, ls in tests:
    card(x, R3y, W, R3h, "white", None, title, edge=BLUE, ls=ls, lw=1.3)
    ax.text(x + 0.014, R3y + R3h - 0.062, body, ha="left", va="top", fontsize=6.6, color=INK, linespacing=1.35)
for i in range(3):
    arrow((XS[i] + W / 2, R2y - 0.002), (XS[i] + W / 2, R3y + R3h + 0.002))

# legend + footer
ly = 0.028
ax.plot([0.012, 0.045], [ly, ly], color=BLUE, lw=1.3); ax.text(0.05, ly, "pre-registered", va="center", fontsize=6.5, color=INK2)
ax.plot([0.175, 0.208], [ly, ly], color=BLUE, lw=1.3, ls="--"); ax.text(0.213, ly, "pre-registered, not yet run", va="center", fontsize=6.5, color=INK2)
ax.text(0.992, ly, "Schematic: curves and dots are illustrative, not data.",
        ha="right", va="center", fontsize=6, color=INK2, style="italic", linespacing=1.2)

ax.text(0.5, 0.003, "* USFLUX and TOTUSJH available in ≥18 of the preceding 24 hourly records.", ha="center", va="bottom", fontsize=5.8, color=INK2)
print(save(fig, "F1_method_updated", "f1_method_updated.py"))
